function compute(state) {
  var f = state.f, fs = state.fs, PI2 = 2 * Math.PI;
  var t = [], y = [];
  for (var i = 0; i <= 600; i++) { var ti = i / 600; t.push(ti); y.push(Math.sin(PI2 * f * ti)); }
  var k = Math.round(f / fs), fp = f - k * fs;
  var ts = [], ys = [], yr = [];
  for (var n = 0; n <= fs; n++) { var tn = n / fs; ts.push(tn); ys.push(Math.sin(PI2 * f * tn)); }
  for (var j = 0; j <= 600; j++) yr.push(Math.sin(PI2 * fp * t[j]));
  return {
    values: { nyquist: fs / 2, alias: Math.abs(fp), aliased: f > fs / 2 ? 1 : 0, max_sample_err: Math.max.apply(null, ts.map(function (tn, n) { return Math.abs(ys[n] - Math.sin(PI2 * fp * tn)); })) },
    series: { t: t, y: y, ts: ts, ys: ys, yr: yr, fx: [f, Math.abs(fp)], fy: [1, 1] }
  };
}
